 dll=managed/(a.assembly+'.dll');cmd=['C:/Program Files/dotnet/dotnet.exe',compiler,'-nologo','-target:library','-nostdlib+','-deterministic','-out:'+str(dll)]+['-r:'+str(p) for p in refs]+[str(executed)];p=subprocess.run(cmd,capture_output=True,text=True,encoding='utf-8',errors='replace');(work/'compile.log').write_text(json.dumps(cmd,ensure_ascii=False)+'\n'+p.stdout+'\n'+p.stderr,encoding='utf-8')
 if p.returncode:raise SystemExit('Driver compile exit '+str(p.returncode))
